fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> Vec<f64> {
    let mut result = Vec::with_capacity(indices.len());
    for (col, &row_idx) in indices.iter().enumerate() {
        // Safety: we assume row_idx < choices.len() and each row has at least indices.len() columns
        let value = choices[row_idx as usize][col];
        result.push(value);
    }
    result
}

